"use client";
import { useState, useEffect } from "react";
import axios from "axios";
import Link from "next/link";
import { IconButton } from "@mui/material";
import { Edit as EditIcon, Delete as DeleteIcon } from "@mui/icons-material";
import Sidebar from "../components/sidebar";
import Navbar from "../components/Navbar";

export default function GestionGroupes() {
  const [groupes, setGroupes] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [groupesResponse, etudiantsResponse] = await Promise.all([
        axios.get("http://localhost:5000/api/groupes"),
        axios.get("http://localhost:5000/api/etudiants"),
      ]);

      // Création d'une map pour retrouver les étudiants par leur idGroupe
      const etudiantsMap = new Map();
      etudiantsResponse.data.forEach((etudiant) => {
        if (!etudiantsMap.has(etudiant.idGroupe)) {
          etudiantsMap.set(etudiant.idGroupe, []);
        }
        etudiantsMap.get(etudiant.idGroupe).push(`${etudiant.nom} ${etudiant.prenom}`);
      });

      // Ajout des étudiants au niveau de chaque groupe
      const groupesData = groupesResponse.data.map((groupe) => ({
        ...groupe,
        tuteurName: `${groupe.tuteur?.nom || "-"} ${groupe.tuteur?.prenom || "-"}`,
        sujetName: groupe.sujet?.nomSujet || "-",
        etudiants: etudiantsMap.get(groupe.idGroupe) || [],
      }));

      setGroupes(groupesData);
    } catch (error) {
      console.error("Erreur lors de la récupération des données :", error);
    } finally {
      setLoading(false);
    }
  };

  const deleteGroupe = async (idGroupe) => {
    if (!window.confirm("Voulez-vous vraiment supprimer ce groupe ?")) return;

    try {
      await axios.delete(`http://localhost:5000/api/supprimerGroupe/${idGroupe}`);
      alert("Groupe supprimé avec succès");
      setGroupes((prevGroupes) =>
        prevGroupes.filter((groupe) => groupe.idGroupe !== idGroupe)
      );
    } catch (error) {
      console.error("Erreur lors de la suppression du groupe :", error);
      alert("Erreur lors de la suppression du groupe");
    }
  };

  return (
    <div className="flex h-screen bg-gray-100">
      {/* Sidebar */}
      <Sidebar className="hidden lg:block bg-blue-700 text-white p-4 w-64 shadow-lg" />

      {/* Main Content */}
      <div className="flex flex-col w-full bg-gray-50">
        {/* Navbar */}
        <Navbar className="bg-blue-600 text-white p-4 shadow-md" />

        <div className="container mx-auto p-6">
          {/* Title */}
          <h2 className="text-2xl font-bold mb-4 text-blue-600">Liste des Groupes</h2>

          {/* Loading State */}
          {loading && <p className="text-center text-gray-500">Chargement...</p>}

          {/* Group Table */}
          {!loading && (
            <table className="min-w-full bg-white border border-gray-300 shadow-md rounded-lg">
              <thead className="bg-blue-500">
                <tr>
                  <th className="border px-4 py-2 text-left text-white">Nom du Groupe et Étudiants</th>
                  <th className="border px-4 py-2 text-left text-white">Tuteur</th>
                  <th className="border px-4 py-2 text-left text-white">Sujet</th>
                  <th className="border px-4 py-2 text-left text-white">Actions</th>
                </tr>
              </thead>
              <tbody>
                {groupes.map((groupe) => (
                  <tr key={groupe.idGroupe} className="hover:bg-gray-50">
                    <td className="border px-4 py-2">
                      <strong>{groupe.nomGroupe}</strong>
                      {groupe.etudiants.length > 0 ? (
                        <ul className="ml-4 list-disc">
                          {groupe.etudiants.map((etudiant, index) => (
                            <li key={index}>{etudiant}</li>
                          ))}
                        </ul>
                      ) : (
                        <span>Aucun étudiant dans ce groupe</span>
                      )}
                    </td>
                    <td className="border px-4 py-2">{groupe.tuteurName || "-"}</td>
                    <td className="border px-4 py-2">{groupe.sujetName || "-"}</td>
                    <td className="border px-4 py-2 flex items-center gap-2">
                      <Link href={`/groupes/edit/${groupe.idGroupe}`} passHref>
                        <IconButton color="primary" title="Éditer">
                          <EditIcon />
                        </IconButton>
                      </Link>
                      <IconButton
                        color="error"
                        onClick={() => deleteGroupe(groupe.idGroupe)}
                        title="Supprimer"
                      >
                        <DeleteIcon />
                      </IconButton>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}